        internal void RunBasicRamTests_Click(object s, RoutedEventArgs e) => _ = RunRamSequence(includeFullScan: false);
        internal void RunAdvancedRamTests_Click(object s, RoutedEventArgs e) => _ = RunRamSequence(includeFullScan: true);

        private async Task RunRamSequence(bool includeFullScan)
        {
            // Something is already running — pressing the active button stops the current sequence.
            if (_ramSequenceCts != null && !_ramSequenceCts.IsCancellationRequested)
            {
                _ramSequenceCts.Cancel();
                return;
            }

            _ramSequenceCts?.Dispose();
            _ramSequenceCts = new CancellationTokenSource();
            var ct = _ramSequenceCts.Token;

            var btnBasic = FindName("BtnRamBasic") as System.Windows.Controls.Button;
            var btnAdvanced = FindName("BtnRamAdvanced") as System.Windows.Controls.Button;
            var activeBtn = includeFullScan ? btnAdvanced : btnBasic;
            var otherBtn = includeFullScan ? btnBasic : btnAdvanced;
            var statusTb = includeFullScan
                ? (FindName("TxtRamAdvDesc") as System.Windows.Controls.TextBlock)
                : TxtRamRunAllDesc;
            var seqPb = includeFullScan
                ? (FindName("PbRamAdvSeq") as System.Windows.Controls.ProgressBar)
                : (FindName("PbRamBasicSeq") as System.Windows.Controls.ProgressBar);
            if (seqPb != null) seqPb.Visibility = Visibility.Visible;
            if (statusTb != null) statusTb.Visibility = Visibility.Visible;

            // the button's usual look (blue in Basic, plain in Advanced), which it returns to after the test
            var idleLook = (activeBtn as Wpf.Ui.Controls.Button)?.Appearance ?? Wpf.Ui.Controls.ControlAppearance.Secondary;
            if (activeBtn != null)
            {
                activeBtn.Content = LanguageService.S("Common", "Stop");
                SetStopLook(activeBtn, running: true);
            }
            if (otherBtn != null) otherBtn.IsEnabled = false;
            SetNavTaskBadge("TaskBadgeRam", true);

            var tileGrid = includeFullScan
                ? (FindName("RamAdvTileGrid") as System.Windows.Controls.Panel)
                : (FindName("RamBasicTileGrid") as System.Windows.Controls.Panel);
            var warningBanner = FindName("RamAdvWarningBanner") as Border;
            var warningText = FindName("TxtRamAdvWarningText") as System.Windows.Controls.TextBlock;
            if (tileGrid != null) { tileGrid.Children.Clear(); tileGrid.Visibility = Visibility.Collapsed; }
            if (includeFullScan && warningBanner != null) warningBanner.Visibility = Visibility.Collapsed;

            int totalSteps = includeFullScan ? 5 : 4;
            if (statusTb != null) statusTb.Text = $"Running 1/{totalSteps} — Bandwidth...";

            var summary = new System.Collections.Generic.List<(string Icon, string Name, string Value, string Sub, bool? Passed, int LedTier)>();

            try
            {
                // 1/N — Bandwidth
                string bwText = "Testing...";
                try
                {
                    var bw = await SMDWin.Services.RamBandwidthService.RunAsync(phase =>
                        Dispatcher.InvokeAsync(() => { if (statusTb != null) statusTb.Text = $"Running 1/{totalSteps} — {phase}"; }));
                    ct.ThrowIfCancellationRequested();
                    string rating = RateRamBandwidth(bw.ReadGBs, bw.WriteGBs);
                    bwText = $"{bw.ReadGBs:F1} / {bw.WriteGBs:F1} GB/s";
                    double bwAvg = (bw.ReadGBs + bw.WriteGBs) / 2.0;
                    int bwTier = bwAvg >= 10 ? 2 : bwAvg >= 5 ? 1 : 0;
                    summary.Add(("🚀", "Bandwidth", bwText, rating, null, bwTier));
                }
                catch (OperationCanceledException) { throw; }
                catch (Exception ex) { AppLogger.Warning(ex, "RunRamSequence(Bandwidth)"); summary.Add(("🚀", "Bandwidth", "Test failed", "", false, 0)); }

                // 2/N — Latency
                if (statusTb != null) statusTb.Text = $"Running 2/{totalSteps} — Latency...";
                try
                {
                    double ns = await SMDWin.Services.RamLatencyBenchmark.RunAsync(ct, phase =>
                        Dispatcher.InvokeAsync(() => { if (statusTb != null) statusTb.Text = $"Running 2/{totalSteps} — {phase}"; }));
                    ct.ThrowIfCancellationRequested();
                    if (ns > 0)
                    {
                        int nsTier = ns <= 70 ? 2 : ns <= 90 ? 1 : 0;
                        summary.Add(("⏱", "Latency", $"{ns:F1} ns", RateRamLatency(ns), null, nsTier));
                    }
                    else summary.Add(("⏱", "Latency", "Test failed", "", false, 0));
                }
                catch (OperationCanceledException) { throw; }
                catch (Exception ex) { AppLogger.Warning(ex, "RunRamSequence(Latency)"); summary.Add(("⏱", "Latency", "Test failed", "", false, 0)); }

                // 3/N — Integrity (RamTestService — 6 patterns + walking bit over 1GB)
                if (statusTb != null) statusTb.Text = $"Running 3/{totalSteps} — Integrity...";
                string lastIntegrityStatus = "";
                SMDWin.Services.RamTestProgress? lastIntegrityProgress = null;
                try
                {
                    var integrityProgress = new Progress<SMDWin.Services.RamTestProgress>(p =>
                    {
                        lastIntegrityStatus = p.StatusText;
                        lastIntegrityProgress = p;
                        Dispatcher.InvokeAsync(() => { if (statusTb != null) statusTb.Text = $"Running 3/{totalSteps} — {p.StatusText}"; });
                    });
                    await _ramTestSvc.RunAsync(1024, integrityProgress, ct);
                    ct.ThrowIfCancellationRequested();
                    long integrityErrors = lastIntegrityProgress?.ErrorCount ?? -1;
                    bool passed = integrityErrors == 0 || lastIntegrityStatus.StartsWith("✅");
                    bool failed = integrityErrors > 0  || lastIntegrityStatus.StartsWith("❌");
                    summary.Add(("🧩", "Integrity", failed ? "FAILED" : "PASSED", "1 GB, 6 patterns",
                        failed ? false : (passed ? true : (bool?)null), failed ? 0 : passed ? 2 : 1));
                }
                catch (OperationCanceledException) { throw; }
                catch (Exception ex) { AppLogger.Warning(ex, "RunRamSequence(Integrity)"); summary.Add(("🧩", "Integrity", "Test failed", "", false, 0)); }

                // 4/N — Walking Bit
                if (statusTb != null) statusTb.Text = $"Running 4/{totalSteps} — Walking Bit...";
                string lastWalkingStatus = "";
                SMDWin.Services.WalkingBitProgress? lastWalkingProgress = null;
                try
                {
                    var svc = new SMDWin.Services.RamDiagnosticsService();
                    var wbProgress = new Progress<SMDWin.Services.WalkingBitProgress>(p =>
                    {
                        lastWalkingStatus = p.StatusText;
                        lastWalkingProgress = p;
                        Dispatcher.InvokeAsync(() => { if (statusTb != null) statusTb.Text = $"Running 4/{totalSteps} — {p.StatusText}"; });
                    });
                    await svc.RunWalkingBitTestAsync(1024, wbProgress, ct);
                    ct.ThrowIfCancellationRequested();
                    long walkingErrors = lastWalkingProgress?.ErrorCount ?? -1;
                    bool passed = walkingErrors == 0 || lastWalkingStatus.StartsWith("✅");
                    bool failed = walkingErrors > 0  || lastWalkingStatus.StartsWith("❌");
                    summary.Add(("👣", "Walking bit", failed ? "FAILED" : "PASSED", "1 GB",
                        failed ? false : (passed ? true : (bool?)null), failed ? 0 : passed ? 2 : 1));
                }
                catch (OperationCanceledException) { throw; }
                catch (Exception ex) { AppLogger.Warning(ex, "RunRamSequence(WalkingBit)"); summary.Add(("👣", "Walking bit", "Test failed", "", false, 0)); }

                // 5/5 — Full Memory Scan (Advanced only)
                bool fullScanSkipped = false;
                if (includeFullScan)
                {
                    if (statusTb != null) statusTb.Text = $"Running 5/{totalSteps} — Full memory scan...";
                    try
                    {
                        long targetMB = SMDWin.Services.RamFullScanService.ComputeTargetMB();
                        if (targetMB <= 0)
                        {
                            // appears as a result in the row (with the explanation in the tooltip), not as a separate strip that makes the card taller
                            fullScanSkipped = true;
                            summary.Add(("🔍", "Full scan", "Skipped", "Not enough free RAM for a safe scan — close some programs and run it again.", null, 1));
                        }
                        else
                        {
                            SMDWin.Services.RamFullScanService.FullScanProgress? lastScanProgress = null;
                            var scanProgress = new Progress<SMDWin.Services.RamFullScanService.FullScanProgress>(p =>
                            {
                                lastScanProgress = p;
                                _ = Dispatcher.InvokeAsync(() => { if (statusTb != null) statusTb.Text = $"Running 5/{totalSteps} — {p.StatusText}"; });
                            });
                            await SMDWin.Services.RamFullScanService.RunAsync(scanProgress, ct);
                            ct.ThrowIfCancellationRequested();
                            long fsErrors = lastScanProgress?.ErrorCount ?? -1;
                            bool fsIncomplete = lastScanProgress != null && lastScanProgress.TotalChunks > 0
                                && lastScanProgress.ChunkIndex < lastScanProgress.TotalChunks;
                            string fsValue = fsErrors < 0 ? "Inconclusive"
                                : fsErrors > 0 ? "Errors found"
                                : fsIncomplete ? "No errors (partial)" : "No errors";
                            bool? fsPassed = fsErrors < 0 ? (bool?)null : fsErrors == 0;
                            int fsLed = fsErrors < 0 ? 1 : fsErrors > 0 ? 0 : 2;
                            summary.Add(("🔍", "Full scan", fsValue, $"~{targetMB / 1024.0:F1} GB scanned", fsPassed, fsLed));
                        }
                    }
                    catch (OperationCanceledException) { throw; }
                    catch (Exception ex)
                    {
                        AppLogger.Warning(ex, "RunRamSequence(FullScan)");
                        summary.Add(("🔍", "Full scan", "Scan failed", "", false, 0));
                    }
                }

                // The results: a compact box for each test, on a single row, in the test's row.
                if (tileGrid != null)
                {
                    if (tileGrid is System.Windows.Controls.Primitives.UniformGrid ug) { ug.Rows = 1; ug.Columns = Math.Max(1, summary.Count); }
                    foreach (var (icon, name, value, sub, _, ledTier) in summary)
                        tileGrid.Children.Add(BuildRamResultTile(icon, name, value, sub, ledTier));
                    tileGrid.Visibility = summary.Count > 0 ? Visibility.Visible : Visibility.Collapsed;
                }

                // ── Summary pill ("4/4 passed" / "3/4 · 1 warning") ──
                int passedCount = summary.Count(x => x.Passed != false);
                int totalCount = summary.Count;
                if (fullScanSkipped) passedCount--;   // the skipped test is in the list, but it did not pass
                int warnCount = (summary.Count(x => x.Passed == false)) + (fullScanSkipped ? 1 : 0);
                UpdateRamSummaryPill(includeFullScan, passedCount, totalCount, warnCount);

                // the last result, for the Health window: "FAILED" = errors found in memory,
                // "… failed" = the test could not run to the end
                TestResultStore.SaveRam(new RamTestRecord
                {
                    When = DateTime.Now,
                    Advanced = includeFullScan,
                    Failed = summary.Where(x => x.Passed == false && (x.Value == "FAILED" || (x.Name == "Full scan" && !x.Value.Contains("failed")))).Select(x => x.Name).ToList(),
                    Incomplete = summary.Where(x => x.Value is "Test failed" or "Scan failed").Select(x => x.Name).ToList(),
                });

                bool anyFailed = summary.Any(x => x.Passed == false);
                if (statusTb != null)
                {
                    // the test description comes back (for the next run), but while the results are shown it is hidden:
                    // the row has room for the title + results, not for a whole sentence too
                    statusTb.Text = includeFullScan
                        ? "All basic tests + full memory scan — longer, depends on free RAM"
                        : "Bandwidth, latency, integrity & walking bit — 1-3 minutes";
                    statusTb.Visibility = summary.Count > 0 ? Visibility.Collapsed : Visibility.Visible;
                }

                // The Integrity/Walking Bit result can mark the DIMMs as faulty, like the individual test (SetModuleResults) — see
                // StartRamTest_Click.
                SetModuleResults(anyFailed ? "ERR" : null);
            }
            catch (OperationCanceledException)
            {
                if (statusTb != null) statusTb.Text = "⚪ Stopped";
            }
            finally
            {
                MemoryRelease.AfterLargeTest("the memory test");
                if (activeBtn != null)
                {
                    activeBtn.Content = LanguageService.S("Common", "Run");
                    activeBtn.ClearValue(System.Windows.Controls.Control.BackgroundProperty);
                    activeBtn.ClearValue(System.Windows.Controls.Control.ForegroundProperty);
                    SetStopLook(activeBtn, running: false, idleLook);
                }
                if (otherBtn != null) otherBtn.IsEnabled = true;
                if (seqPb != null) seqPb.Visibility = Visibility.Collapsed;
                SetNavTaskBadge("TaskBadgeRam", false);
            }
        }

        private Border BuildRamResultTile(string icon, string name, string value, string sub, int ledTier)
        {
            string ledKey = ledTier >= 2 ? "StatusOkBrush" : ledTier == 1 ? "StatusWarnBrush" : "StatusCritBrush";

            // two small lines: the test name with the status dot, then the result; the details stay in the tooltip
            var head = new StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 1) };
            var led = new System.Windows.Shapes.Ellipse { Width = 7, Height = 7, VerticalAlignment = System.Windows.VerticalAlignment.Center, Margin = new Thickness(0, 0, 5, 0) };
            led.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, ledKey);
            head.Children.Add(led);
            var lblName = new System.Windows.Controls.TextBlock { Text = name, FontSize = Ui.FontXS, FontWeight = FontWeights.SemiBold, Opacity = 0.8 };
            lblName.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, "TextSecondaryBrush");
            head.Children.Add(lblName);

            var lblValue = new System.Windows.Controls.TextBlock
            {
                Text = value, FontSize = Ui.FontM, FontWeight = FontWeights.SemiBold, TextTrimming = TextTrimming.CharacterEllipsis,
            };
            lblValue.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, ledTier == 0 ? "StatusCritBrush" : "TextPrimaryBrush");

            var stack = new StackPanel();
            stack.Children.Add(head);
            stack.Children.Add(lblValue);
            _ = icon;   // emoji icons are no longer shown: the coloured dot gives the state

            var tile = new Border
            {
                Margin = new Thickness(3, 0, 3, 0), Padding = new Thickness(9, 4, 9, 5),
                CornerRadius = new CornerRadius(6), BorderThickness = new Thickness(1),
                Child = stack,
                ToolTip = string.IsNullOrEmpty(sub) ? $"{name}: {value}" : $"{name}: {value}\n{sub}",
            };
            tile.SetResourceReference(Border.BorderBrushProperty, "CardBorderBrush");
            return tile;
        }

        private void UpdateRamSummaryPill(bool advanced, int passedCount, int totalCount, int warnCount)
        {
            var pill = FindName(advanced ? "RamAdvSummaryPill" : "RamBasicSummaryPill") as Border;
            var txt = FindName(advanced ? "TxtRamAdvSummaryPill" : "TxtRamBasicSummaryPill") as System.Windows.Controls.TextBlock;
            if (pill == null || txt == null) return;

            bool ok = warnCount == 0;
            pill.SetResourceReference(Border.BackgroundProperty, ok ? "StatusOkBgBrush" : "StatusWarnBgBrush");
            txt.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, ok ? "StatusOkBrush" : "StatusWarnBrush");
            txt.Text = ok ? $"{passedCount}/{totalCount} passed" : $"{passedCount}/{totalCount} · {warnCount} warning{(warnCount > 1 ? "s" : "")}";
            pill.Visibility = Visibility.Visible;
        }

        private async void RunRamBench_Click(object s, RoutedEventArgs e)
        {
            if (FindName("BtnRamBench") is System.Windows.Controls.Button btn) btn.IsEnabled = false;
            SetNavTaskBadge("TaskBadgeRam", true);
            var descTb = FindName("TxtRamBandwidthDesc") as System.Windows.Controls.TextBlock;
            string originalDesc = descTb?.Text ?? LanguageService.S("Ram", "BandwidthDefaultLabel");
            if (descTb != null) descTb.Text = LanguageService.S("Common", "Starting");
            try
            {
                var result = await SMDWin.Services.RamBandwidthService.RunAsync(phase =>
                {
                    Dispatcher.InvokeAsync(() => { if (descTb != null) descTb.Text = phase; });
                });
                double readGBs = result.ReadGBs, writeGBs = result.WriteGBs;
                string rating = RateRamBandwidth(readGBs, writeGBs);
                if (descTb != null)
                {
                    descTb.Text = $"{readGBs:F1} / {writeGBs:F1} GB/s  ·  {rating}";
                    // Details (number of passes + note) — in the tooltip, no visual space taken
                    descTb.ToolTip = $"{_LS("Ram", "SyntheticTestNote")}  ·  {result.WritePasses} write + {result.ReadPasses} read passes";
                }
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "RunRamBench_Click");
                if (descTb != null) descTb.Text = _LS("Common", "TestFailed");
            }
            finally { if (FindName("BtnRamBench") is System.Windows.Controls.Button b) b.IsEnabled = true; SetNavTaskBadge("TaskBadgeRam", false); }
            _ = originalDesc; // kept for clarity — do not return to the initial description after the test
        }

        // DDR3 ≈ 10-20 GB/s | DDR4 ≈ 25-45 GB/s | DDR5 ≈ 50-90 GB/s (a synthetic single-thread test usually measures below
        // the theoretical bus peaks)
        private string RateRamBandwidth(double readGBs, double writeGBs)
        {
            double avg = (readGBs + writeGBs) / 2.0;
            string label = avg >= 40 ? _LS("Common", "Excellent")
                          : avg >= 20 ? _LS("Common", "VeryGood")
                          : avg >= 10 ? _LS("Common", "Good")
                          : avg >= 5  ? _LS("Common", "Average")
                          : _LS("Common", "Low");
            return label;
        }

        private async void RunRamLatency_Click(object s, RoutedEventArgs e)
        {
            if (FindName("BtnRamLatency") is System.Windows.Controls.Button btn) btn.IsEnabled = false;
            SetNavTaskBadge("TaskBadgeRam", true);
            var descTb = FindName("TxtRamLatencyDesc") as System.Windows.Controls.TextBlock;
            if (descTb != null) descTb.Text = LanguageService.S("Common", "Starting");
            try
            {
                double ns = await SMDWin.Services.RamLatencyBenchmark.RunAsync(default, phase =>
                {
                    Dispatcher.InvokeAsync(() => { if (descTb != null) descTb.Text = phase; });
                });
                if (descTb != null)
                    descTb.Text = ns > 0 ? $"{ns:F1} ns  ·  {RateRamLatency(ns)}" : _LS("Common", "TestFailed");
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "RunRamLatency_Click");
                if (descTb != null) descTb.Text = _LS("Common", "TestFailed");
            }
            finally { if (FindName("BtnRamLatency") is System.Windows.Controls.Button b) b.IsEnabled = true; SetNavTaskBadge("TaskBadgeRam", false); }
        }

        // Typical DRAM latency: DDR3 ~40-70ns | DDR4 ~50-80ns | DDR5 ~60-90ns
        // (varies a lot with CAS latency and frequency — indicative thresholds)
        private string RateRamLatency(double ns)
        {
            if (ns <= 0) return "";
            return ns <= 50 ? _LS("Common", "Excellent")
                 : ns <= 70 ? _LS("Common", "Good")
                 : ns <= 90 ? _LS("Common", "Average")
                 : _LS("Common", "Slow");
        }

        private async void RunWalkingBit_Click(object s, RoutedEventArgs e)
        {
            if (FindName("BtnWalkingBit") is System.Windows.Controls.Button btn) btn.IsEnabled = false;
            SetNavTaskBadge("TaskBadgeRam", true);
            var descTb = FindName("TxtRamWalkingBitDesc") as System.Windows.Controls.TextBlock;
            try
            {
                var svc = new SMDWin.Services.RamDiagnosticsService();
                var cts = new System.Threading.CancellationTokenSource(TimeSpan.FromMinutes(5));
                var prog = new Progress<SMDWin.Services.WalkingBitProgress>(p =>
                {
                    Dispatcher.InvokeAsync(() =>
                    {
                        if (descTb == null) return;
                        if (!p.IsFinished)
                        {
                            descTb.Text = p.StatusText;
                            return;
                        }
                        bool passed = p.Passed;
                        descTb.Text = passed
                            ? "No errors detected  ·  1 GB"
                            : $"{p.ErrorCount} error(s) — RAM may be faulty";
                        descTb.Foreground = new SolidColorBrush(passed
                            ? WpfColor.FromRgb(34, 197, 94)   // green
                            : WpfColor.FromRgb(239, 68, 68)); // red
                    });
                });
                await svc.RunWalkingBitTestAsync(1024, prog, cts.Token);
            }
            catch (Exception ex) { AppLogger.Warning(ex, "RunWalkingBit_Click"); }
            finally { if (FindName("BtnWalkingBit") is System.Windows.Controls.Button b) b.IsEnabled = true; SetNavTaskBadge("TaskBadgeRam", false); }
        }

        internal void OpenMemDiag_Click(object s, RoutedEventArgs e)
        {
            try { System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("mdsched.exe") { UseShellExecute = true }); }
            catch (Exception ex) { AppLogger.Warning(ex, "OpenMemDiag_Click"); }
        }
